'use strict';
// Local, seeded financial market. Its RNG never consumes transport randomness.
const MARKET_STOCKS=[
 ['常星存储','存储芯片',7.21,600,300,'chip'],['钟芯国际','晶圆代工',6.57,1000,700,'chip'],['钟际旭创','高速光模块',9.49,200,100,'tech'],
 ['凝德时代','动力与储能电池',8.62,500,300,'energy'],['彼亚笛','新能源汽车',3.32,900,500,'energy'],['龙基绿能','光伏',7.75,800,600,'energy'],
 ['恒睿医药','创新药',6.94,600,400,'health'],['山壹重工','工程机械',8.52,900,700,'industry'],['梓金矿业','铜金矿产',8.91,3000,2500,'resource'],
 ['龙国石油','石油与天然气',1.15,18000,15000,'resource'],['钟远海控','集装箱航运',2.71,1600,1000,'industry'],['龙国平安','保险与综合金融',5.88,1800,1200,'finance'],
 ['昭商银行','商业银行',9.38,2500,2000,'finance'],['龙国移栋','电信运营',6.93,2200,1000,'tech'],['贵洲茅酒','白酒',7.14,250,150,'consumer']
].map(([name,industry,initial,total,float,sector],i)=>({id:i,name,industry,initial,total:total*10000,float:float*10000,sector,code:'G'+String(i+1).padStart(2,'0')}));
const MARKET_CYCLE=[{name:'调整年',min:-.20,max:-.10},{name:'震荡年',min:-.05,max:.05},{name:'调整年',min:-.20,max:-.10},{name:'牛市年',min:.25,max:.45},{name:'震荡年',min:-.05,max:.05}];
const FINANCE_HISTORY_LIMIT=3650;
let marketTab='wealth',marketSelected=0,marketRange=30;
function marketHash(str){let h=2166136261;for(let c of String(str)){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return h>>>0;}
function marketRng(seed){let state=seed>>>0;return ()=>{state=(state+0x6D2B79F5)>>>0;let z=state;z=Math.imul(z^(z>>>15),z|1);z^=z+Math.imul(z^(z>>>7),z|61);return ((z^(z>>>14))>>>0)/4294967296;};}
function marketNormal(random){return Math.sqrt(-2*Math.log(Math.max(1e-12,random())))*Math.cos(2*Math.PI*random());}
function marketGamma(a,random){if(a<1)return marketGamma(a+1,random)*Math.pow(Math.max(1e-12,random()),1/a);let d=a-1/3,c=1/Math.sqrt(9*d);for(let k=0;k<10000;k++){let x=marketNormal(random),v=1+c*x;if(v<=0)continue;v=v*v*v;let u=random();if(u<1-.0331*x*x*x*x||Math.log(Math.max(1e-12,u))<.5*x*x+d*(1-v+Math.log(v)))return d*v;}throw Error('无法生成金融报价');}
function financeState(){return S.financial??={version:1,seed:marketHash('east-coast-finance:'+S.seed),syncedAt:S.day,wealthNav:1,wealthLots:[],nextLot:1,
 deposited:0,withdrawn:0,periodFlow:0,lastReportAssets:0,lastReportDay:Math.floor(S.day-.375),lastReport:null,curve:[],market:null,notified:{bank:false,broker:false},everBank:false,everBroker:false};}
const freshMarketBefore=fresh;fresh=function(){let x=freshMarketBefore();x.financial=null;x.stockPathRevision=4;return x;};
function financialCities(type){return realCities().filter(c=>!c.dormant&&!c.removed&&c.shape===2&&c.size>=(type==='bank'?1:2));}
function financeBuildingCount(type){return realCities().reduce((n,c)=>n+(c.financeBuildings?.[type]||0),0);}
function financeCanInvest(type){return financialCities(type).some(c=>(c.financeBuildings?.[type]||0)>0);}
function financeUnlocked(type='bank'){let f=financeState();return type==='broker'?!!(f.everBroker||financeBuildingCount('broker')):!!(f.everBank||financeBuildingCount('bank')||f.everBroker);}
function syncFinanceEntry(){let on=financeUnlocked(),el=$('market');if(el){el.hidden=false;el.disabled=false;el.classList.toggle('is-locked',!on);el.title=on?'金融市场':'建设银行后解锁金融市场';el.setAttribute('aria-label',on?'金融市场':'金融（未解锁，点击查看建设条件）');}document.querySelector?.('footer .dock')?.classList.remove('finance-locked');}
function financeCityIcons(){return `<span class="finance-city-icons" role="img" aria-label="金融城市图标：圆环内菱形，颜色不限">${COLORS.map(color=>`<svg viewBox="0 0 32 32" width="32" height="32" aria-hidden="true"><circle cx="16" cy="16" r="13" fill="white" stroke="#334b4e" stroke-width="2"/><path d="M16 6 25 16 16 26 7 16Z" fill="${color}"/></svg>`).join('')}</span>`;}
function showFinanceLock(type='bank'){let bank=financeUnlocked(),broker=financeUnlocked('broker');openModal(`<div class="financial-market"><div class="modal-head"><h2>${type==='broker'?'股票市场尚未解锁':'金融市场尚未解锁'}</h2><button class="close" onclick="closeModal()" aria-label="关闭解锁说明">×</button></div><div class="finance-unlock-city">${financeCityIcons()}<div><b>商业金融城市 · 圆环内菱形</b><p>颜色不限，让这类城市通过交通任务成长。</p></div></div><section class="market-product"><h3>银行${bank?'已建设':'尚未建设'}</h3><p>金融城市达到<b>中层级（中型及以上）</b>后，可在城市详情建设银行，费用<b>¥100</b>。建成后开放金融市场与银行理财。</p>${!bank&&financialCities('bank').length?'<button class="primary" onclick="showFinanceConstruction(&quot;bank&quot;)">查看银行建设</button>':''}</section><section class="market-product"><h3>证券公司${broker?'已建设':'尚未建设'}</h3><p>金融城市达到<b>高层级（大型）</b>后，可建设证券公司，费用<b>¥150</b>；需先建成银行。建成后开放股票市场。</p>${bank&&!broker&&financialCities('broker').length?'<button class="primary" onclick="showFinanceConstruction(&quot;broker&quot;)">查看证券公司建设</button>':''}</section><button class="primary" onclick="closeModal()">知道了</button></div>`);}
function financialReturn(){let f=financeState();return f.deposited>0?financialProfit()/f.deposited:0;}
function nextMarketNine(day){return Math.floor(day-.375+1e-9)+1+.375;}
function openStockMarket(){let f=financeState();if(f.market||!financeUnlocked('broker'))return;let now=S.day;f.market={openedAt:now,nextAt:nextMarketNine(now),days:0,year:0,plan:null,
 stocks:MARKET_STOCKS.map(c=>({price:c.initial,previous:c.initial,shares:0,cost:0,realized:0,limitUsed:false,limitRemaining:0})),history:[{day:now,prices:MARKET_STOCKS.map(c=>c.initial)}]};}
function buildFinance(id,type){if(type==='broker'&&!financeUnlocked())return toast('请先建设银行，再开通证券业务');let c=S.cities[id],price=type==='bank'?100:type==='broker'?150:NaN;if(!Number.isFinite(price)||!financialCities(type).some(x=>x.id===id)||S.lives<=0)return toast('当前城市尚未满足建设条件');if(S.points<price)return toast('建设需要 ¥'+price);syncFinancial();spend(price,'financialBuildings',c.name+'建设'+(type==='bank'?'银行':'证券公司'));c.financeBuildings??={bank:0,broker:0};c.financeBuildings[type]=(c.financeBuildings[type]||0)+1;let f=financeState();if(type==='bank')f.everBank=true;else{f.everBroker=true;openStockMarket();}save();updateUI();showFinancialMarket(type==='bank'?'wealth':'stocks');toast((type==='bank'?'银行':'证券公司')+'已建成');}
const STOCK_PATH_MODEL='regime-news-v4';
function generateRegimeYear(seed,year,api){
 const random=api.marketRng(api.marketHash(seed+':regime-news-v4:'+year)),normal=()=>api.marketNormal(random),D=365,phase=year%5;
 const prior=[-.14,0,-.14,.22,0][phase],weights=phase===3?[.15,.35,.50]:phase===0||phase===2?[.50,.35,.15]:[.30,.40,.30];
 const draw=w=>{let u=random(),sum=0;for(let i=0;i<w.length;i++){sum+=w[i];if(u<sum)return i;}return w.length-1;};
 const market=[],marketStates=[],sector={},events=[];
 let state=1,until=0,stressUntil=0;
 for(let d=0;d<D;d++){
  if(d>=until){state=draw(weights);until=d+10+Math.floor(random()*31);marketStates.push({start:d,end:Math.min(D,until),state:state-1});}
  const vol=state===0?1.25:state===2?1.05:.80;
  let shock=random()<.008?(random()<.5?-1:1)*(.018+random()*.035):0;if(shock<-.025)stressUntil=d+8;
  const sigma=.0055*vol*(d<stressUntil?1.5:1);
  market.push({signal:.5*Math.log1p(prior)/D+[-.0009,0,.0008][state]+sigma*normal()+shock,sigma});
 }
 for(let name of [...new Set(api.MARKET_STOCKS.map(s=>s.sector))]){
  let out=[],regime=0,end=0;
  for(let d=0;d<D;d++){if(d>=end){regime=draw([.30,.40,.30])-1;end=d+12+Math.floor(random()*34);}out.push(regime*.00035+.0055*normal());}sector[name]=out;
 }
 const returns=api.MARKET_STOCKS.map((stock,id)=>{
  const beta={consumer:.75,finance:.85,industry:1,resource:1.15,chip:1.2,tech:1.2,energy:1.1,health:1.05}[stock.sector]||1;
  const baseSigma=(.010+random()*.005)*Math.sqrt(beta),news=Array(D).fill(0);
  // Unverified information can be confirmed, disappointed or delayed; reactions are not fixed reversals.
  let count=Number(random()<.65)+Number(random()<.25);
  for(let j=0;j<count;j++){
   const start=5+Math.floor(random()*320),rise=1+Math.floor(random()*3),gap=3+Math.floor(random()*7),settle=1+Math.floor(random()*4),gain=.04+random()*.10,kind=draw([.30,.50,.20]);
   const follow=kind===0?gain*(random()*.5):kind===1?-gain*(1.2+random()*.8):-gain*(.2+random()*.6);
   for(let k=0;k<rise;k++)news[start+k]+=Math.log1p(gain)/rise;
   for(let k=0;k<settle;k++)news[start+rise+gap+k]+=follow/settle;
   events.push({stock:id,type:['confirmation','disappointment','unresolved'][kind],start,followAt:start+rise+gap,end:start+rise+gap+settle});
  }
  if(random()<(phase===3?.08:phase===1||phase===4?.05:.04)){
   const start=10+Math.floor(random()*330),span=2+Math.floor(random()*4),up=random()<(phase===3?.60:phase===0||phase===2?.45:.50),gain=up?.20+random()*.30:-.15-random()*.20;
   for(let k=0;k<span;k++)news[start+k]+=Math.log1p(gain)/span;
   events.push({stock:id,type:up?'rarePositive':'rareNegative',start,end:start+span});
  }
  let quality=0,qualityUntil=0,vol=1,volUntil=0,out=[];
  for(let d=0;d<D;d++){
   if(d>=qualityUntil){quality=draw([.30,.40,.30])-1;qualityUntil=d+45+Math.floor(random()*76);}
   if(d>=volUntil){vol=.7+random()*.8;volUntil=d+8+Math.floor(random()*21);}
   const sigma=baseSigma*vol,variance=sigma*sigma+.0055*.0055+beta*beta*market[d].sigma*market[d].sigma;
   const surprise=random()<.0018?(random()<.5?-1:1)*(.03+random()*.09):0;
   let raw=beta*market[d].signal+sector[stock.sector][d]+quality*.00025-.5*variance+sigma*normal()+news[d]+surprise;
   out.push(Math.exp(Math.max(Math.log(.8),Math.min(Math.log(1.2),raw))));
  }
  return out;
 });
 const annual=returns.map(rs=>rs.reduce((a,b)=>a*b,1)),target=annual.reduce((s,x)=>s+x,0)/annual.length-1;
 return {year,target,annual,returns,periods:[],events,marketStates,pathModel:'regime-news-v4',backgroundPrior:prior};
}
function generateMarketYear(seed,year){return generateRegimeYear(seed,year,{marketRng,marketHash,marketNormal,MARKET_STOCKS});}
function wealthMultiplier(seed,day){let random=marketRng(marketHash(seed+':wealth:'+day)),a=25.59948940485559,b=51.41542105173251,x=marketGamma(a,random),y=marketGamma(b,random);return .95+.15*x/(x+y);}
function wealthValue(){let f=financeState();return f.wealthLots.reduce((sum,l)=>sum+l.units*f.wealthNav,0);}
function stockValue(){let m=financeState().market;return m?m.stocks.reduce((sum,s)=>sum+s.shares*s.price,0):0;}
function financialAssets(){return wealthValue()+stockValue();}
function financialProfit(){let f=financeState();return financialAssets()+f.withdrawn-f.deposited;}
function advanceWealth(to){let f=financeState(),cursor=f.syncedAt;if(to<=cursor)return;while(cursor<to-1e-10){let day=Math.floor(cursor-.375+1e-9),end=Math.min(to,day+1+.375);if(end<=cursor)end=Math.min(to,cursor+1);if(f.rateDay!==day){f.rateDay=day;f.rate=wealthMultiplier(f.seed,day);}f.wealthNav*=Math.pow(f.rate,end-cursor);cursor=end;}f.syncedAt=to;}
function settleStockDay(){let f=financeState(),m=f.market;if(!m)return;let year=Math.floor(m.days/365),index=m.days%365;if(!m.plan||m.plan.year!==year||m.plan.pathModel!==STOCK_PATH_MODEL)m.plan=generateMarketYear(f.seed,year);m.year=year;for(let i=0;i<15;i++){let s=m.stocks[i],mult=m.plan.returns[i][index];s.previous=s.price;if(s.limitRemaining>0){mult=1.2;s.limitRemaining--;}s.price*=mult;}m.days++;m.history.push({day:m.nextAt,prices:m.stocks.map(s=>s.price)});if(m.history.length>FINANCE_HISTORY_LIMIT+1)m.history.shift();m.nextAt+=1;}
function financialDailyReport(day){let f=financeState(),value=financialAssets(),profit=value-f.lastReportAssets-f.periodFlow;let base=value-profit;f.lastReport={day,profit,rate:base>0?profit/base:profit===0?0:null,wealth:wealthValue(),stocks:stockValue(),assets:value};f.lastReportDay=Math.floor(day-.375+1e-9);f.lastReportAssets=value;f.periodFlow=0;f.curve.push({day,profit:financialProfit(),assets:value,rate:financialReturn()});if(f.curve.length>FINANCE_HISTORY_LIMIT)f.curve.shift();}
function syncFinancial(){let f=financeState(),now=S.day;if(!financeUnlocked()){f.syncedAt=now;f.lastReportDay=Math.floor(now-.375+1e-9);return;}if(now<f.syncedAt-1e-8)return;let nextReport=f.lastReportDay+1+.375;while(nextReport<=now+1e-9){advanceWealth(nextReport);while(f.market&&f.market.nextAt<=nextReport+1e-9)settleStockDay();financialDailyReport(nextReport);nextReport=f.lastReportDay+1+.375;}advanceWealth(now);while(f.market&&f.market.nextAt<=now+1e-9)settleStockDay();}
function financeNotice(){let f=financeState();if(modalOpen||draft||bridgeDraft||S.lives<=0)return;let type=!f.notified.bank&&financialCities('bank').length?'bank':!f.notified.broker&&financialCities('broker').length?'broker':null;if(!type)return;f.notified[type]=true;save();let bank=type==='bank';openModal(`<div class="modal-head"><span class="eyebrow">新设施已解锁</span><button class="close" onclick="closeModal()">×</button></div><h1>${bank?'银行可以建设了':'证券业务已开放'}</h1><p>${bank?'中级金融城市已出现。建设银行需要100，建成后可购买理财，持有到下一游戏日即可赎回。':'高级金融城市已出现。建设证券公司需要150，建成后15只股票开始每日涨跌，不持仓也会持续运行。'}</p><div class="ux-actions"><button class="primary" onclick="showFinanceConstruction('${bank?'bank':'broker'}')">查看建设</button><button onclick="closeModal()">稍后建设</button></div>`);}
const tickMarketBefore=tick;tick=function(dt){tickMarketBefore(dt);syncFinancial();financeNotice();};
function financeInput(id){let value=Number($(id)?.value);return Number.isFinite(value)?value:NaN;}
function buyWealth(amount=financeInput('wealth-amount')){syncFinancial();if(!financeCanInvest('bank')||S.lives<=0)return toast('需要一座正在运营的银行');if(!Number.isFinite(amount)||amount<.01||amount>S.points)return toast('请输入不超过现金余额的有效金额');amount=Math.floor((amount+1e-8)*100)/100;let f=financeState();spend(amount,'financialInvestment','购买理财');f.wealthLots.push({id:f.nextLot++,units:amount/f.wealthNav,principal:amount,boughtAt:S.day,unlockDay:Math.floor(S.day)+1});f.deposited+=amount;f.periodFlow+=amount;save();updateUI();showFinancialMarket('wealth');}
function redeemWealth(id){syncFinancial();let f=financeState(),lot=f.wealthLots.find(l=>l.id===id);if(!lot||S.lives<=0)return;if(Math.floor(S.day)<lot.unlockDay)return toast('这笔理财需下一游戏日才能赎回');let amount=Math.floor((lot.units*f.wealthNav+1e-9)*100)/100;f.wealthLots=f.wealthLots.filter(l=>l.id!==id);f.withdrawn+=amount;f.periodFlow-=amount;if(amount>0)credit(amount,'financialRedemptions','理财赎回');save();updateUI();showFinancialMarket('wealth');}
function tradeStock(id,side,quantity=financeInput('stock-quantity')){syncFinancial();let f=financeState(),m=f.market,s=m?.stocks[id],c=MARKET_STOCKS[id];if(!s||!c||S.lives<=0)return;quantity=Number(quantity);if(!Number.isSafeInteger(quantity)||quantity<=0)return toast('请输入正整数股数，1股即可交易');let buying=side==='buy';if(!buying&&side!=='sell')return;if(buying&&!financeCanInvest('broker'))return toast('需要一座正在运营的证券公司');if(buying&&quantity>c.float-s.shares)return toast('超过市场剩余流通股数');if(!buying&&quantity>s.shares)return toast('超过当前持股数量');let amount=buying?Math.ceil((quantity*s.price-1e-9)*100)/100:Math.floor((quantity*s.price+1e-9)*100)/100;if(buying){if(amount>S.points)return toast('可用现金不足');spend(amount,'financialInvestment','买入'+c.name+' '+quantity+'股');s.cost+=amount;s.shares+=quantity;f.deposited+=amount;f.periodFlow+=amount;if(!s.limitUsed&&s.shares>=c.float*.1){s.limitUsed=true;s.limitRemaining=3;toast('大额持仓事件 · '+c.name+'市场关注度上升');}}else{let cost=s.cost*quantity/s.shares;s.shares-=quantity;s.cost=Math.max(0,s.cost-cost);if(s.realizedCost===undefined&&s.realized!==0)s.legacyRealizedBasis=true;s.realizedCost=(s.realizedCost||0)+cost;s.realized+=amount-cost;f.withdrawn+=amount;f.periodFlow-=amount;if(amount>0)credit(amount,'financialRedemptions','卖出'+c.name+' '+quantity+'股');}save();updateUI();showFinancialMarket('stocks');}
function marketMoney(n){return '¥'+Number(n).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});}
function marketSigned(n){return (n>0?'+':'')+Number(n).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});}
function marketPercent(n){if(!Number.isFinite(n))return '—';return (n>0?'+':'')+(100*n).toFixed(2)+'%';}
function marketShares(n){return n>=1e8?(n/1e8).toLocaleString('zh-CN')+'亿股':n>=1e4?(n/1e4).toLocaleString('zh-CN')+'万股':n.toLocaleString('zh-CN')+'股';}
function marketPrice(n){return n>=.01?n.toFixed(2):n.toPrecision(3);}
function marketClock(){let minutes=Math.floor((S.day%1)*1440);return String(Math.floor(minutes/60)).padStart(2,'0')+':'+String(minutes%60).padStart(2,'0');}
function marketChart(data,label,price=false){if(!data.length)return '<div class="market-chart-empty">首个交易日结算后显示收益曲线</div>';let selected=data.slice(-(marketRange||FINANCE_HISTORY_LIMIT)),values=selected.map(x=>x.value),min=Math.min(...values),max=Math.max(...values),range=Math.max(.001,max-min),w=720,h=200,pad=56;let points=selected.map((x,i)=>[(pad+i*(w-pad*2)/Math.max(1,selected.length-1)).toFixed(2),(h-32-(x.value-min)/range*(h-64)).toFixed(2)]);let color=values.at(-1)>=values[0]?'#b25a44':'#34775b';return `<figure class="market-chart"><figcaption>${label}<span>${marketRange?'最近'+marketRange+'日':'最近10年'}</span></figcaption><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${label}，起始${marketPercent(values[0])}，最新${marketPercent(values.at(-1))}"><path d="M32 168H688M32 100H688M32 32H688" stroke="#dde5de" fill="none"/><text x="4" y="25">${marketPercent(max)}</text><text x="4" y="190">${marketPercent(min)}</text><polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${color}" stroke-width="2.5" stroke-linejoin="round"/><text x="32" y="190">第${Math.floor(selected[0].day)+1}天</text><text x="610" y="190">第${Math.floor(selected.at(-1).day)+1}天</text></svg></figure>`;}
function marketRangeButtons(){return `<div class="market-range" aria-label="曲线时间范围">${[7,30,365,0].map(n=>`<button class="${marketRange===n?'active':''}" onclick="marketRange=${n};showFinancialMarket()">${n?n+'日':'全部'}</button>`).join('')}</div>`;}
function financeBuildSection(type){let bank=type==='bank',cities=financialCities(type);return `<section class="market-build"><div><h3>${bank?'银行':'证券公司'}建设 <small>¥${bank?100:150} / 座</small></h3><p>${bank?'中级及以上金融城市可建。多座银行共享理财账户，收益倍率不叠加。':'高级金融城市可建。多座证券公司共享行情与持仓，建新公司不会重置股价。'}</p></div>${cities.length?cities.map(c=>`<div class="market-build-row"><span>${escapeHTML(c.name)}<small>已有${c.financeBuildings?.[type]||0}座</small></span><button onclick="buildFinance(${c.id},'${type}')" ${S.points<(bank?100:150)||S.lives<=0?'disabled':''}>建设 · ¥${bank?100:150}</button></div>`).join(''):`<p class="market-muted">等待${bank?'中级':'高级'}金融城市出现后开放建设。</p>`}</section>`;}
function wealthPanel(){let f=financeState(),value=wealthValue();return `${financeBuildSection('bank')}${!financeUnlocked('broker')?financeBuildSection('broker'):''}<section class="market-product"><span class="eyebrow">每日浮动 · 次日可取</span><h2>灵活理财</h2><p>每日涨跌 −5%～+10%，按实际持有时间累计涨跌；收益可能增加，也可能减少。下一游戏日可赎回，不必存满一周。</p><div class="market-metrics"><div><small>当前理财资产</small><strong>${marketMoney(value)}</strong></div><div><small>持有笔数</small><strong>${f.wealthLots.length}</strong></div></div><div class="market-order"><label for="wealth-amount">投入金额（元）<input id="wealth-amount" type="number" min="0.01" step="0.01" inputmode="decimal" placeholder="输入金额"></label><button class="primary" onclick="buyWealth()" ${!financeCanInvest('bank')||S.lives<=0?'disabled':''}>购买理财</button></div>${f.wealthLots.length?`<div class="market-lots">${f.wealthLots.map(l=>{let current=l.units*f.wealthNav,unlocked=Math.floor(S.day)>=l.unlockDay;return `<div class="market-build-row"><span><b>${marketMoney(current)}</b><small>本金${marketMoney(l.principal)} · 持有${(S.day-l.boughtAt).toFixed(2)}天 · 收益率${marketPercent(current/l.principal-1)}</small></span><button onclick="redeemWealth(${l.id})" ${!unlocked||S.lives<=0?'disabled':''}>${unlocked?'赎回':'第'+(l.unlockDay+1)+'天可取'}</button></div>`;}).join('')}</div>`:'<p class="market-muted">尚未持有理财，投入资金后会在这里显示。</p>'}</section>`;}
function stockPanel(){let f=financeState(),m=f.market;if(!financeUnlocked('broker')||!m)return `${financeBuildSection('broker')}<section class="market-product"><h2>15家公司，一个持续运行的市场</h2><p>首家证券公司建成后开市。每只初始股价1—10元，未买入也会每天涨跌；每游戏日09:00发布上一交易日行情。</p></section>`;let id=marketSelected,s=m.stocks[id],c=MARKET_STOCKS[id],change=s.price/s.previous-1,pnl=s.shares*s.price-s.cost;return `${financeBuildSection('broker')}<p class="market-muted">市场第${Math.floor(Math.max(0,m.days-1)/365)+1}年 · 已结算${m.days}个交易日 · 每日09:00更新</p><div class="market-stock-layout"><section><div class="market-list-heading"><span>公司 / 行业</span><span>最新 / 日涨跌</span></div><div class="market-stock-list">${MARKET_STOCKS.map((v,i)=>{let st=m.stocks[i],r=st.price/st.previous-1;return `<button class="market-stock ${i===id?'selected':''}" onclick="marketSelected=${i};showFinancialMarket('stocks')" aria-pressed="${i===id}"><span><b>${v.name}</b><small>${v.code} · ${v.industry}</small></span><span><b>¥${marketPrice(st.price)}</b><small class="${r>=0?'positive':'negative'}">${marketPercent(r)}</small></span></button>`;}).join('')}</div></section><section class="market-stock-detail"><span class="eyebrow">${c.code} · ${c.industry}</span><h2>${c.name}</h2><div class="market-quote"><strong>¥${marketPrice(s.price)}</strong><span class="${change>=0?'positive':'negative'}">${marketPercent(change)}</span></div>${marketRangeButtons()}${marketChart(m.history.map(h=>({day:h.day,value:h.prices[id]/c.initial-1})),'相对开市涨跌幅',true)}<div class="market-metrics compact"><div><small>总股本 / 市值</small><b>${marketShares(c.total)} / ${marketMoney(c.total*s.price)}</b></div><div><small>流通股 / 剩余可买</small><b>${marketShares(c.float)} / ${marketShares(c.float-s.shares)}</b></div><div><small>我的持仓 / 市值</small><b>${marketShares(s.shares)} / ${marketMoney(s.shares*s.price)}</b></div><div><small>持仓收益率 / 已实现收益率</small><b class="${pnl>=0?'positive':'negative'}">${marketPercent(s.cost>0?pnl/s.cost:0)} / ${marketPercent(s.legacyRealizedBasis?null:s.realizedCost>0?s.realized/s.realizedCost:s.realized===0?0:null)}</b></div></div><div class="market-order"><label for="stock-quantity">交易股数（1股起）<input id="stock-quantity" type="number" min="1" step="1" inputmode="numeric" value="1" oninput="updateStockOrderQuote(${id})"></label><button class="primary" onclick="tradeStock(${id},'buy')" ${!financeCanInvest('broker')||S.lives<=0?'disabled':''}>买入</button><button onclick="tradeStock(${id},'sell')" ${s.shares<1||S.lives<=0?'disabled':''}>卖出</button></div><p id="stock-order-quote" class="market-muted">买入1股约需 ${marketMoney(Math.ceil((s.price-1e-9)*100)/100)}。</p><p class="market-muted">按当前报价成交，无100股一手限制。成交金额精确到分。每日涨跌上限±20%。</p></section></div>`;}
function portfolioPanel(){let f=financeState(),value=financialAssets(),profit=financialProfit();return `<div class="market-metrics"><div><small>投资资产</small><strong>${marketMoney(value)}</strong></div><div><small>累计投资收益率</small><strong class="${profit>=0?'positive':'negative'}">${marketPercent(financialReturn())}</strong></div><div><small>累计转入 / 转出</small><strong>${marketMoney(f.deposited)} / ${marketMoney(f.withdrawn)}</strong></div></div><p class="market-muted">累计收益率＝（当前投资资产＋累计转出−累计转入）÷累计转入本金。追加本金不算盈利，赎回和卖出不算亏损。可用现金及交通经营收支不计入这条收益曲线。</p>${marketRangeButtons()}${marketChart(f.curve.filter(x=>Number.isFinite(x.rate)).map(x=>({day:x.day,value:x.rate})),'累计投资收益率')}<section class="market-product"><h3>每日结算</h3><p>每天游戏时间09:00公布上一交易日的投资盈亏，已公布的账单不会被今天的买卖改写。暂停、关闭页面时游戏时间不推进。</p><p>行情有调整、震荡和牛市倾向，但全年结果并不固定。行业和公司消息可能带来机会，也可能出现反弹后回落；少数股票会走出大行情，历史涨幅不保证延续。</p></section>`;}
function showFinancialMarket(tab){if(!financeUnlocked())return showFinanceLock('bank');if((tab||marketTab)==='stocks'&&!financeUnlocked('broker'))return showFinanceLock('broker');if(tab)marketTab=tab;syncFinancial();let f=financeState(),profit=financialProfit(),report=f.lastReport;openModal(`<div class="financial-market"><div class="modal-head"><div><span class="eyebrow">EAST COAST · FINANCIAL MARKET</span><h2>金融市场</h2></div><button class="close" onclick="closeModal()" aria-label="关闭金融市场">×</button></div><div class="market-headline"><div><small>可用现金</small><b>${marketMoney(S.points)}</b></div><div><small>累计投资收益率</small><b class="${profit>=0?'positive':'negative'}">${marketPercent(financialReturn())}</b></div><div><small>游戏时间 / 昨日收益率</small><b>${marketClock()} / ${report?marketPercent(report.rate):'等待09:00结算'}</b></div></div><nav class="market-tabs" aria-label="金融市场分区">${[['wealth','银行理财'],['stocks','股票市场'],['portfolio','收益记录']].map(([key,label])=>`<button class="${marketTab===key?'active':''} ${key==='stocks'&&!financeUnlocked('broker')?'is-locked':''}" title="${key==='stocks'&&!financeUnlocked('broker')?'建设证券公司后开放，点击查看条件':label}" onclick="showFinancialMarket('${key}')" aria-pressed="${marketTab===key}">${label}</button>`).join('')}</nav>${marketTab==='wealth'?wealthPanel():marketTab==='stocks'?stockPanel():portfolioPanel()}</div>`);}
function showFinanceConstruction(type='bank'){if(type==='broker'&&!financeUnlocked())return toast('先建银行，再建设证券公司');openModal(`<div class="modal-head"><h2>金融设施建设</h2><button class="close" onclick="closeModal()">×</button></div>${financeBuildSection(type)}`);}
const cityFinanceBefore=showCityEconomy;showCityEconomy=function(id){cityFinanceBefore(id);let c=S.cities[id];if(c.shape===2)$('modal-content').innerHTML+=`<section class="infra-card"><h3>金融设施</h3><p>银行${c.financeBuildings?.bank||0}座 · 证券公司${c.financeBuildings?.broker||0}座</p>${['bank','broker'].map(type=>`<button onclick="buildFinance(${id},'${type}')" ${!financialCities(type).some(x=>x.id===id)||(type==='broker'&&!financeUnlocked())?'disabled':''}>${type==='bank'?'建设银行 ¥100':'建设证券公司 ¥150'}</button>`).join('')}${financeUnlocked()?'<button onclick="showFinancialMarket()">进入金融市场</button>':'<p>中级金融城市建银行后开放金融入口；高级金融城市建券商后开放股票。</p>'}</section>`;};
const operationsMarketBefore=showOperations;showOperations=function(){operationsMarketBefore();if(financeUnlocked())$('modal-content').innerHTML+=`<section class="infra-card"><h3>金融市场</h3><p>银行理财、股票与百分比收益记录。</p><button onclick="showFinancialMarket()">进入金融市场</button><button onclick="showFinanceConstruction('broker')">证券公司建设</button></section>`;};
const financeLedgerBefore=showFinance;showFinance=function(){financeLedgerBefore();if(financeUnlocked())$('modal-content').innerHTML+=`<section class="infra-card"><h3>投资账户</h3><p>投资资产 ${marketMoney(financialAssets())} · 累计收益率 ${marketPercent(financialReturn())}<br>金融建筑支出 ${marketMoney(S.ledger.financialBuildings||0)}；投资转入、转出不计交通营业利润。</p><button onclick="showFinancialMarket('portfolio')">查看收益记录</button></section>`;};
const updateFinanceBefore=updateUI;updateUI=function(){updateFinanceBefore();syncFinanceEntry();};
$('market').onclick=()=>showFinancialMarket();financeState();syncFinanceEntry();S.stockPathRevision=4;save();

function updateStockOrderQuote(id){let s=financeState().market?.stocks[id],q=financeInput('stock-quantity'),el=$('stock-order-quote');if(!s||!el)return;el.textContent=Number.isSafeInteger(q)&&q>0?'买入'+q.toLocaleString('zh-CN')+'股约需 '+marketMoney(Math.ceil((q*s.price-1e-9)*100)/100)+'；当前持有'+s.shares.toLocaleString('zh-CN')+'股。':'请输入正整数股数。';}
